-- faqs (14)
insert into public.faqs (key, question, answer, category, display_order, is_published, is_demo) values
  ('faq-pricing', 'How much does an accountant cost?', 'It depends on the structure of your business, your turnover, how many transactions you have and which services you need. Our published plans start from a monthly fee for sole traders and rise for limited companies and businesses with payroll and management reporting. We quote in writing after a short consultation, so you know the number before you commit to anything.', 'pricing', 1, true, true),
  ('faq-sole-traders', 'Do you work with sole traders?', 'Yes. A large part of our client base is self-employed people and freelancers who want Self Assessment handled properly and a clear view of what they owe. We also give an honest answer on whether incorporating would benefit you, which sometimes means telling you it would not.', 'services', 2, true, true),
  ('faq-corporation-tax', 'Can you handle Corporation Tax?', 'Yes. We prepare the computation and the CT600 return, file it with HMRC alongside your statutory accounts, and tell you what to pay and by when. We also review the position during the year, while there is still time for planning to make a difference.', 'services', 3, true, true),
  ('faq-vat', 'Can you manage VAT?', 'Yes. We handle VAT registration, help you choose the scheme that fits how you trade, and file your quarterly returns under Making Tax Digital. If you are approaching the registration threshold we will flag it before it becomes urgent.', 'services', 4, true, true),
  ('faq-vat-threshold', 'When does my business need to register for VAT?', 'You must register when your VAT-taxable turnover over any rolling twelve-month period passes the registration threshold, or if you expect to pass it within the next thirty days on its own. The threshold is set by HMRC and can change at a Budget, so we monitor your rolling turnover rather than checking once a year. You can also register voluntarily below the threshold, which sometimes makes sense if your customers are VAT-registered.', 'services', 5, true, true),
  ('faq-payroll', 'Can you handle payroll?', 'Yes. We run weekly or monthly payroll, make the Real Time Information submissions to HMRC, distribute payslips, handle starters and leavers, and manage pension auto-enrolment submissions. You get a summary each period showing what is due to HMRC and when.', 'services', 6, true, true),
  ('faq-switching', 'Can you take over from my current accountant?', 'Yes, and it is more routine than most people expect. You tell your current accountant you are moving, we write to them for professional clearance and your records, and we take it from there. You do not need to have an awkward conversation about why, and you do not have to wait for a year end to move.', 'switching', 7, true, true),
  ('faq-remote', 'Do you work remotely?', 'Yes. Most of our work happens over video call, phone and email, and our clients are spread across the UK rather than clustered around one office. If you would rather meet in person we can arrange that, but nothing about the service depends on it.', 'working-together', 8, true, true),
  ('faq-onboarding', 'How does onboarding work?', 'We start with a consultation to understand your business and confirm what you need. You get a written quote. If you go ahead, we complete the identity checks required of accountancy firms, request records from your previous accountant if there is one, get you set up on the software, and agree the deadlines for the year ahead. Most clients are fully onboarded within a couple of weeks.', 'working-together', 9, true, true),
  ('faq-consultation', 'Can I book a free consultation?', 'Yes. The initial consultation is free and there is no obligation attached to it. It is a conversation about your business and what you need, not a sales call with a deadline on it. You can book a time directly through the website.', 'general', 10, true, true),
  ('faq-software', 'Which accounting software do you work with?', 'We work with the major UK cloud accounting platforms and will usually keep you on whatever you already use rather than forcing a migration. If you are not using anything yet, we will recommend something that fits the size and shape of your business.', 'working-together', 11, true, true),
  ('faq-deadlines', 'What happens if I miss a filing deadline?', 'Companies House and HMRC both charge automatic penalties for late filing, and these escalate the longer a filing is outstanding. Interest can also apply to tax paid late. We track your filing dates and remind you well ahead of each one, which is the entire point of having them tracked by somebody.', 'general', 12, true, true),
  ('faq-advisory', 'What is the difference between compliance and advisory work?', 'Compliance is the work that has to be done: accounts, tax returns, VAT, payroll. It describes what already happened. Advisory work is about what happens next — whether you can afford a hire, what a price change does to your margin, how much cash you will have in three months. Both matter, but only one of them changes the outcome.', 'services', 13, true, true),
  ('faq-contract', 'Am I tied into a long contract?', 'No. We work on a rolling monthly basis. If the service is not right for you, you can leave with a month''s notice and we will pass your records on to whoever takes over.', 'pricing', 14, true, true)
on conflict (key) do update set
  question = excluded.question,
  answer = excluded.answer,
  category = excluded.category,
  display_order = excluded.display_order,
  is_published = excluded.is_published,
  is_demo = excluded.is_demo;

-- services (6)
insert into public.services (key, slug, title, summary, icon, intro, includes, outcomes, seo, display_order, is_active, is_demo) values
  ('svc-accounting', 'accounting', 'Accounting', 'Annual accounts and ongoing accounting support.', 'ledger', 'We prepare your year-end accounts, file them where they need to go, and make sure you actually understand what they say. Most of our clients come to us because their previous accounts arrived nine months late with no explanation attached.', '{"Year-end statutory accounts prepared and filed with Companies House","Sole trader and partnership accounts","Companies House confirmation statement","Director''s Self Assessment where it forms part of your plan","A year-end review call to walk through the numbers","Ongoing questions answered without a per-email charge"}', '[{"problem":"Accounts arrive months late, long after they are useful.","outcome":"We agree a timetable at the start of the year and tell you what we need and when."},{"problem":"The numbers are filed but nobody explains them.","outcome":"Every set of accounts comes with a short review call in plain English."},{"problem":"Deadlines creep up and penalties follow.","outcome":"Filing dates are tracked for you, with reminders well ahead of time."}]'::jsonb, '{"title":"Accounting services for UK businesses","description":"Year-end accounts, Companies House filing and ongoing accounting support for sole traders, contractors and limited companies. Book a free consultation.","canonicalPath":"/services/accounting"}'::jsonb, 1, true, true),
  ('svc-tax', 'tax', 'Corporation Tax', 'Clear tax preparation and planning for limited companies.', 'percent', 'Corporation Tax is where a lot of avoidable cost sits. We prepare and file your return, and we look at the position early enough in the year that there is still something useful to do about it.', '{"Corporation Tax computation and CT600 return","Filing with HMRC alongside your statutory accounts","Review of allowable expenses and capital allowances","Salary and dividend planning for director-shareholders","Guidance on the payment deadline and how much to set aside","Support with HMRC correspondence and queries"}', '[{"problem":"The tax bill is a surprise every year.","outcome":"We give you a running estimate so you can put money aside as you go."},{"problem":"Planning conversations happen after the year has ended.","outcome":"We review your position mid-year, while decisions can still change the outcome."},{"problem":"Nobody explains what is actually claimable.","outcome":"We go through your costs with you rather than guessing from a bank feed."}]'::jsonb, '{"title":"Corporation Tax accountants","description":"Corporation Tax returns, computations and planning for UK limited companies. Clear advice on what you owe and when. Book a free consultation.","canonicalPath":"/services/tax"}'::jsonb, 2, true, true),
  ('svc-bookkeeping', 'bookkeeping', 'Bookkeeping', 'Accurate bookkeeping so the business always knows where it stands.', 'receipt', 'Good bookkeeping is not admin for its own sake. It is what makes every other number — your tax estimate, your VAT return, your margin — worth trusting. We keep it current so you are never working from a six-month-old picture.', '{"Monthly or quarterly bookkeeping","Bank reconciliation and transaction categorisation","Sales and purchase ledger maintenance","Receipt capture set up on software you already use","Month-end review and a short summary of what changed","Clean records handed straight through to VAT and year-end"}', '[{"problem":"Records are reconstructed in a panic at year end.","outcome":"Books are kept current month by month, so year end is a review rather than a rebuild."},{"problem":"Reports do not match reality.","outcome":"Reconciled accounts mean the reports you look at are the ones we work from."},{"problem":"Chasing paperwork eats evenings and weekends.","outcome":"Receipt capture and bank feeds cut the manual work down to a few minutes a week."}]'::jsonb, '{"title":"Bookkeeping services","description":"Monthly and quarterly bookkeeping, bank reconciliation and receipt capture for UK businesses. Keep your numbers current. Book a free consultation.","canonicalPath":"/services/bookkeeping"}'::jsonb, 3, true, true),
  ('svc-payroll', 'payroll', 'Payroll', 'Reliable payroll processing and reporting.', 'people', 'Payroll has to be right and it has to be on time, every month, without you chasing it. We run it, file it and tell you what is leaving the bank account and when.', '{"Monthly or weekly payroll processing","Real Time Information submissions to HMRC","Payslips distributed to your team","Starters, leavers, P45s and P60s","Auto-enrolment pension submissions","A clear monthly summary of PAYE and National Insurance due"}', '[{"problem":"Payroll is one more thing to remember each month.","outcome":"We run to a fixed schedule and only come to you when something has changed."},{"problem":"It is never clear what is owed to HMRC.","outcome":"Every run comes with the payment amount, the reference and the due date."},{"problem":"New starters create a scramble.","outcome":"Send us the details and we handle the onboarding paperwork."}]'::jsonb, '{"title":"Payroll services for UK employers","description":"Monthly payroll processing, RTI submissions, payslips and auto-enrolment for UK employers. Book a free consultation.","canonicalPath":"/services/payroll"}'::jsonb, 4, true, true),
  ('svc-vat', 'vat', 'VAT', 'VAT registration, returns and support.', 'chart', 'VAT is where small process problems turn into real money. We handle registration, choose the scheme that suits how you actually trade, and file your returns under Making Tax Digital.', '{"VAT registration and scheme selection","Quarterly VAT returns filed under Making Tax Digital","Flat Rate, Cash Accounting and Annual Accounting reviews","Guidance on the registration threshold as you grow","Support with HMRC VAT queries and inspections","Advice on VAT treatment for unusual or cross-border sales"}', '[{"problem":"It is unclear whether registration is required yet.","outcome":"We monitor your rolling turnover and tell you before it becomes urgent."},{"problem":"The wrong scheme is quietly costing money.","outcome":"We review which VAT scheme fits your margins and your customer base."},{"problem":"Returns are filed late or from incomplete records.","outcome":"Bookkeeping and VAT are handled together, so the return is built from reconciled data."}]'::jsonb, '{"title":"VAT accountants and VAT return services","description":"VAT registration, scheme advice and Making Tax Digital VAT returns for UK businesses. Book a free consultation.","canonicalPath":"/services/vat"}'::jsonb, 5, true, true),
  ('svc-business-advisory', 'business-advisory', 'Business Advisory', 'Financial insight and practical advice to help you make better decisions.', 'compass', 'Compliance tells you what already happened. Advisory work is about what happens next: whether you can afford the hire, what the new pricing does to your margin, how much cash you will have in March.', '{"Monthly or quarterly management accounts","Cash flow forecasting and scenario planning","Pricing and margin analysis","Budgeting and hiring affordability reviews","Business structure reviews as you grow","A regular call with the accountant who knows your numbers"}', '[{"problem":"Decisions get made on gut feel and a bank balance.","outcome":"Management accounts give you a defensible basis for the call."},{"problem":"Cash gets tight without warning.","outcome":"A rolling forecast shows the pinch points far enough ahead to act."},{"problem":"Growth happens but profit does not follow.","outcome":"We break down margin by product, service or client so you can see where it goes."}]'::jsonb, '{"title":"Business advisory and management accounts","description":"Management accounts, cash flow forecasting and practical financial advice for growing UK businesses. Book a free consultation.","canonicalPath":"/services/business-advisory"}'::jsonb, 6, true, true)
on conflict (key) do update set
  slug = excluded.slug,
  title = excluded.title,
  summary = excluded.summary,
  icon = excluded.icon,
  intro = excluded.intro,
  includes = excluded.includes,
  outcomes = excluded.outcomes,
  seo = excluded.seo,
  display_order = excluded.display_order,
  is_active = excluded.is_active,
  is_demo = excluded.is_demo;

