  ('plan-sole-trader', 'sole-trader', 'Sole Trader', 'Self-employed people and freelancers not trading as a company.', 49, 'GBP', 'From', '/month', 'Everything a sole trader needs to stay on top of Self Assessment without thinking about it in January.', '{"Self Assessment prepared and filed","Sole trader accounts","Basic bookkeeping support","Tax calculations and payment reminders","Email support with a named contact"}', 'Get Started', '/contact?plan=sole-trader', false, 1, true, true),
  ('plan-limited-company', 'limited-company', 'Limited Company', 'Contractors and established limited companies.', 99, 'GBP', 'From', '/month', 'Full compliance cover for a limited company, with the planning conversations built in rather than billed extra.', '{"Year-end accounts filed with Companies House","Corporation Tax return and computation","Bookkeeping support","VAT returns under Making Tax Digital","Director payroll","Salary and dividend planning","Unlimited accountant support"}', 'Get Started', '/contact?plan=limited-company', true, 2, true, true),
  ('plan-growing-business', 'growing-business', 'Growing Business', 'Businesses with staff, stock or multiple revenue lines.', 199, 'GBP', 'From', '/month', 'Monthly numbers and a regular conversation about what they mean, on top of everything in the compliance layer.', '{"Monthly bookkeeping","Monthly management accounts","Payroll for your team","VAT returns and scheme reviews","Corporation Tax and tax planning","Cash flow forecasting","Business advisory calls","A dedicated accountant"}', 'Talk to an Accountant', '/book-consultation?plan=growing-business', false, 3, true, true)
