-- testimonials (6)
insert into public.testimonials (key, quote, name, role, company, rating, photo_url, is_featured, display_order, is_demo) values
  ('test-1', 'CloudAccounts made our accounts feel simple for the first time. I finally understand what is happening with the numbers in my business, and I get an answer the same day when I ask something.', 'Sarah Mitchell', 'Director', 'London-based consultancy', 5, null, true, 1, true),
  ('test-2', 'We moved over mid-year, which I was told would be a nightmare. It took one call and a form. The first VAT return went out on time and nothing has been late since.', 'James Okonkwo', 'Founder', 'E-commerce business', 5, null, true, 2, true),
  ('test-3', 'The monthly management accounts changed how we make decisions. We stopped guessing about whether we could afford to hire and started knowing.', 'Priya Raman', 'Managing Director', 'Design studio', 5, null, true, 3, true),
  ('test-4', 'As a contractor I mostly wanted someone to tell me what to pay myself and when. That is exactly what I get, without a lecture attached.', 'Daniel Hughes', 'IT contractor', 'Limited company', 5, null, false, 4, true),
  ('test-5', 'My previous accountant charged for every email. Knowing I can just ask a question has genuinely made me run the business better.', 'Amelia Clarke', 'Owner', 'Independent retailer', 5, null, false, 5, true),
  ('test-6', 'Straightforward, quick to respond, and they explain things without making you feel like you should already have known.', 'Tom Bradley', 'Partner', 'Construction firm', 4, null, false, 6, true)
on conflict (key) do update set
  quote = excluded.quote,
  name = excluded.name,
  role = excluded.role,
  company = excluded.company,
  rating = excluded.rating,
