-- team_members (6)
insert into public.team_members (key, slug, name, role, bio, qualifications, memberships, focus, email, linkedin_url, photo_url, display_order, is_active, is_demo) values
  ('team-1', 'elena-marsh', 'Elena Marsh', 'Founder & Managing Director', 'Elena started CloudAccounts after a decade in practice, frustrated by how often clients received technically correct accounts that nobody had bothered to explain. She leads the firm''s advisory work and still takes on a small portfolio of clients directly.', '{}', '{}', '{"Business advisory","Company structure","Growth planning"}', null, null, null, 1, true, true),
  ('team-2', 'marcus-webb', 'Marcus Webb', 'Head of Tax', 'Marcus looks after Corporation Tax and personal tax planning across the client base. He spends most of his time on the conversations that happen before a year end rather than the filings that follow it.', '{}', '{}', '{"Corporation Tax","Self Assessment","Profit extraction"}', null, null, null, 2, true, true),
  ('team-3', 'hannah-obrien', 'Hannah O''Brien', 'Client Services Manager', 'Hannah runs onboarding and is the person most clients speak to first. She handles the handover from a previous accountant, which is usually the part people expect to be difficult.', '{}', '{}', '{"Onboarding","Client support","Practice operations"}', null, null, null, 3, true, true),
  ('team-4', 'raj-patel', 'Raj Patel', 'Senior Accountant', 'Raj manages a portfolio of limited companies and contractors, covering year-end accounts, VAT and payroll. He is the named contact for a large share of the firm''s contractor clients.', '{}', '{}', '{"Limited companies","VAT","Contractors"}', null, null, null, 4, true, true),
  ('team-5', 'sofia-lindqvist', 'Sofia Lindqvist', 'Bookkeeping Lead', 'Sofia leads the bookkeeping team and owns the month-end process. She is responsible for making sure the data every other service depends on is reconciled and current.', '{}', '{}', '{"Bookkeeping","Month-end reporting","Accounting software"}', null, null, null, 5, true, true),
  ('team-6', 'george-adeyemi', 'George Adeyemi', 'Payroll Manager', 'George runs payroll for the firm''s employer clients, from single-director companies through to teams of fifty, including RTI submissions and pension auto-enrolment.', '{}', '{}', '{"Payroll","Auto-enrolment","Employer compliance"}', null, null, null, 6, true, true)
