-- case_studies (3)
insert into public.case_studies (key, slug, title, sector, headline_metric, headline_metric_label, challenge, solution, result, display_order, is_published, is_demo) values
  ('case-1', 'ecommerce-growth', 'An e-commerce business that had outgrown its bookkeeping', 'E-commerce', '£420k → £1.2m', 'Annual turnover across the engagement', 'The business was growing quickly but its bookkeeping process had not changed since it was one person and a spreadsheet. Stock, marketplace fees and returns were all being recorded inconsistently, so nobody could say which product lines were actually profitable.', 'We rebuilt the chart of accounts around how the business really trades, moved bookkeeping to a monthly cycle, and introduced management accounts that split revenue and margin by channel.', 'The owner moved from an annual view of the business to a monthly one, with clear visibility of margin by channel and a cash flow forecast to plan stock purchasing against.', 1, true, true),
  ('case-2', 'professional-services-admin', 'A professional services firm losing days to finance admin', 'Professional services', '32%', 'Reduction in accounting administration time', 'Two directors were spending several days each month on invoicing, chasing payment, categorising expenses and preparing figures for their accountant — time that came directly out of billable work.', 'We took bookkeeping and payroll in house, set up automated receipt capture and bank feeds, and standardised the month-end pack so the same information arrives in the same format every month.', 'Finance admin moved off the directors'' desks. The monthly close now runs to a fixed timetable and the directors review a report rather than assembling one.', 2, true, true),
  ('case-3', 'consultancy-tax-planning', 'A consultancy where planning happened too late in the year', 'Consultancy', '£18,400', 'Potential tax saving identified through planning', 'Tax was only ever discussed after the year had ended, by which point the decisions that would have changed the outcome had already been made by default.', 'We moved the tax conversation to a mid-year review covering profit extraction, timing of expenditure, capital allowances and pension contributions, so the options were still open.', 'The review identified a set of changes worth a meaningful amount over the year, and the planning call is now a fixed part of the annual cycle rather than an afterthought.', 3, true, true)
