-- guides (3)
insert into public.guides (key, slug, title, summary, format, audience, sections, updated_on, seo, display_order, is_demo) values
  ('guide-new-company', 'starting-a-limited-company', 'Starting a limited company', 'The setup steps that matter in the first month, in the order they need doing.', 'Checklist', 'New company directors', '[{"heading":"Before you incorporate","points":["Check the name is available and not too close to an existing registered company or trade mark.","Decide the share structure now — splitting shares later can have tax consequences.","Choose an accounting reference date; the default is the anniversary of the month you incorporate.","Confirm a registered office address that you are entitled to use."]},{"heading":"In the first fortnight","points":["Open a business bank account in the company''s name and keep it strictly separate from personal money.","Register for Corporation Tax with HMRC.","Register as an employer if you will run payroll, including for a single director.","Set up accounting software before transactions start, not after."]},{"heading":"Before the first quarter ends","points":["Decide whether VAT registration is needed or worthwhile.","Agree how you will pay yourself and document it properly.","Put dividend paperwork in place — board minutes and vouchers, not just a bank transfer.","Diary the filing dates for accounts, Corporation Tax and the confirmation statement."]},{"heading":"Habits worth forming immediately","points":["Photograph receipts at the point of purchase rather than collecting them.","Reconcile the bank monthly.","Keep a separate account for tax and move money into it as you invoice.","Ask before you make a decision with a tax consequence, not after."]}]'::jsonb, '2026-08-12', '{"title":"Starting a limited company: setup checklist","description":"A practical checklist for new UK limited company directors covering incorporation, registrations, banking and the habits that make year one easier.","canonicalPath":"/resources/guides/starting-a-limited-company"}'::jsonb, 0, true),
  ('guide-switching', 'switching-accountants', 'Switching accountants', 'What actually happens when you move, and why it is less disruptive than people expect.', 'Explainer', 'Anyone considering a move', '[{"heading":"You do not have to wait for a year end","points":["You can move at any point in the year; mid-year transfers are routine.","Work already in progress is handed over rather than repeated.","There is no requirement to explain your reasons to anyone."]},{"heading":"The process","points":["You notify your existing accountant that you are moving.","Your new firm writes to them requesting professional clearance and your records.","The existing firm confirms there is no professional reason not to act, and passes over the information.","Your new firm completes the identity and anti-money-laundering checks required of accountancy firms.","Software access and authorisations with HMRC are transferred."]},{"heading":"What to have ready","points":["Your company registration number and UTR.","Access to your accounting software, if you use it.","The most recent set of accounts and tax return.","Details of any outstanding filings or open HMRC correspondence."]},{"heading":"What can slow it down","points":["An outstanding fee with the previous firm — settle it, as clearance can be delayed.","Records that were never digitised.","Filings already overdue, which usually need dealing with first."]}]'::jsonb, '2026-07-30', '{"title":"Switching accountants: how it works","description":"How to change accountants in the UK: professional clearance, transferring records and authorisations, and what can slow the process down.","canonicalPath":"/resources/guides/switching-accountants"}'::jsonb, 1, true),
  ('guide-record-keeping', 'record-keeping-for-small-businesses', 'Record keeping for small businesses', 'What to keep, how long to keep it, and the setup that makes it take minutes a week.', 'Checklist', 'Sole traders and small companies', '[{"heading":"What you need to keep","points":["All sales invoices raised and all purchase invoices and receipts.","Bank and credit card statements for every business account.","Records of anything taken out of the business for personal use.","Payroll records if you employ anyone, including yourself as a director.","VAT records if registered, kept digitally under Making Tax Digital."]},{"heading":"How long to keep it","points":["Retention periods differ between company records and self-employment records, and VAT has its own requirement.","HMRC publishes the current periods — check them rather than assuming a single number covers everything.","Digital copies are generally acceptable, which makes long retention far easier."]},{"heading":"A setup that works","points":["One bank account used exclusively for the business.","Receipt capture on your phone, used at the till rather than later.","Bank feeds into accounting software so transactions arrive automatically.","A fixed monthly slot to reconcile and review."]},{"heading":"The common failures","points":["Mixing personal and business spending in one account.","Keeping receipts as paper in a box.","Recording a transfer between your own accounts as income.","Leaving everything until the filing deadline."]}]'::jsonb, '2026-07-15', '{"title":"Record keeping for small businesses","description":"What records a UK small business must keep, how long to keep them, and a practical setup that takes minutes a week.","canonicalPath":"/resources/guides/record-keeping-for-small-businesses"}'::jsonb, 2, true)
on conflict (key) do update set
  slug = excluded.slug,
  title = excluded.title,
  summary = excluded.summary,
  format = excluded.format,
  audience = excluded.audience,
  sections = excluded.sections,
  updated_on = excluded.updated_on,
  seo = excluded.seo,
  display_order = excluded.display_order,
  is_demo = excluded.is_demo;

